    def _conta_do_identificador(self, tipo: TipoDeIdentificador) -> ContaDeExtrato:
        inicio = self.inicio
        if tipo is TipoDeIdentificador.TXID:
            return self._conta_do_arquivo(arquivo_de_pix_recebidos(inicio, inicio))
