                    r.identificador,
                    r.banco,
                    r.conta,
                    r.data.isoformat(),
                    r.valor_centavos,
                    *_colunas_dos_componentes(r.componentes),
                    r.documento_do_pagador,
                    r.nome_do_pagador,
                )
                for r in retornos
            ],

